# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

namespace {

// float4 vectorized kernel: processes 4 elements per thread
__launch_bounds__(256, 4)
__global__ void fused_post_ops_kernel_vec4(float4* __restrict__ x4, const float* __restrict__ sum,
                                            int64_t numel4, int64_t channels, int64_t spatial) {
    int64_t idx = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx >= numel4) return;

    float4 v4 = x4[idx];
    int64_t base = idx * 4;

    // Process each of the 4 elements
    float vals[4] = {v4.x, v4.y, v4.z, v4.w};
    #pragma unroll
    for (int i = 0; i < 4; i++) {
        int64_t elem_idx = base + i;
        int64_t c = (elem_idx / spatial) % channels;
        float v = vals[i];
        v = v >= 0.0f ? v : 0.2f * v;
        v += sum[c];
        v = v < -1.0f ? -1.0f : (v > 1.0f ? 1.0f : v);
        v = 0.5f * v * (1.0f + erff(v * 0.7071067811865475f));
        vals[i] = v;
    }
    v4.x = vals[0]; v4.y = vals[1]; v4.z = vals[2]; v4.w = vals[3];
    x4[idx] = v4;
}

// Scalar kernel for remainder or fallback
__launch_bounds__(256, 4)
__global__ void fused_post_ops_kernel(float* __restrict__ x, const float* __restrict__ sum,
                                       int64_t numel, int64_t channels, int64_t spatial,
                                       int64_t offset) {
    int64_t idx = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x + offset;
    if (idx >= numel) return;
    int64_t c = (idx / spatial) % channels;
    float v = x[idx];
    v = v >= 0.0f ? v : 0.2f * v;
    v += sum[c];
    v = v < -1.0f ? -1.0f : (v > 1.0f ? 1.0f : v);
    v = 0.5f * v * (1.0f + erff(v * 0.7071067811865475f));
    x[idx] = v;
}

}  // namespace

torch::Tensor fused_post_ops(torch::Tensor x, torch::Tensor sum_tensor) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(sum_tensor.is_cuda(), "sum_tensor must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(sum_tensor.scalar_type() == at::kFloat, "sum_tensor must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be NCDHW");
    TORCH_CHECK(sum_tensor.numel() == x.size(1), "sum_tensor must provide one value per channel");

    auto out = x.contiguous();
    auto sum_flat = sum_tensor.contiguous().view({x.size(1)});

    const int64_t numel = out.numel();
    const int64_t channels = out.size(1);
    const int64_t spatial = out.size(2) * out.size(3) * out.size(4);

    float* out_ptr = out.data_ptr<float>();
    const float* sum_ptr = sum_flat.data_ptr<float>();

    // Check 16-byte alignment for float4 path
    bool aligned = (reinterpret_cast<uintptr_t>(out_ptr) % 16 == 0);
    const int threads = 256;

    if (aligned && numel >= 4) {
        int64_t numel4 = numel / 4;
        int64_t remainder = numel % 4;

        // float4 vectorized path
        int blocks4 = static_cast<int>((numel4 + threads - 1) / threads);
        fused_post_ops_kernel_vec4<<<blocks4, threads>>>(
            reinterpret_cast<float4*>(out_ptr), sum_ptr, numel4, channels, spatial);

        // scalar tail
        if (remainder > 0) {
            int64_t tail_start = numel4 * 4;
            int blocks_tail = static_cast<int>((remainder + threads - 1) / threads);
            fused_post_ops_kernel<<<blocks_tail, threads>>>(
                out_ptr, sum_ptr, numel, channels, spatial, tail_start);
        }
    } else {
        // scalar fallback
        int blocks = static_cast<int>((numel + threads - 1) / threads);
        fused_post_ops_kernel<<<blocks, threads>>>(out_ptr, sum_ptr, numel, channels, spatial, 0);
    }

    return out;
